"""Exact integer rank policies, with cheap isolated policy snapshots."""
from ordered import get, put, items, from_sorted


class SchedulingAlgorithm:
    def rank_cal(self, pkt):
        raise NotImplementedError

    def post_dequeue(self, pkt, rank):
        pass

    def snapshot(self):
        return None

    def restore(self, state):
        pass


class FifoAlgorithm(SchedulingAlgorithm):
    def __init__(self):
        self.time = 0

    def rank_cal(self, pkt):
        self.time += 1
        return self.time

    def snapshot(self):
        return self.time

    def restore(self, state):
        self.time = state

    def certificate(self):
        return {'kind': 'fifo', 'time': self.time}


class SpAlgorithm(SchedulingAlgorithm):
    def __init__(self, flowid2pri):
        self.flowid2pri = dict(flowid2pri)
        self.levels = sorted(self.flowid2pri.items())

    def rank_cal(self, pkt):
        return self.flowid2pri[pkt.flowid]

    def certificate(self):
        return {'kind': 'sp', 'levels': [list(pair) for pair in self.levels]}


class pFabricAlgorithm(SchedulingAlgorithm):
    def rank_cal(self, pkt):
        return pkt.flow_size

    def certificate(self):
        return {'kind': 'sff'}


class WFQAlgorithm(SchedulingAlgorithm):
    def __init__(self, flowid2weight):
        self.flows = from_sorted([(flow, (weight, 0))
                                  for flow, weight in sorted(dict(flowid2weight).items())])
        self.virtual_time = 0

    def rank_cal(self, pkt):
        weight, finish = get(self.flows, pkt.flowid)
        finish = max(finish, self.virtual_time) + (pkt.length * 1048576 + weight - 1) // weight
        self.flows = put(self.flows, pkt.flowid, (weight, finish))
        return finish

    def post_dequeue(self, pkt, rank):
        self.virtual_time = max(self.virtual_time, rank)

    def weight(self, flow, weight):
        _, finish = get(self.flows, flow)
        self.flows = put(self.flows, flow, (weight, finish))

    def snapshot(self):
        return self.flows, self.virtual_time

    def restore(self, state):
        self.flows, self.virtual_time = state

    def certificate(self):
        weights = []
        finish = []
        for flow, (weight, tag) in items(self.flows):
            weights.append([flow, weight])
            finish.append([flow, tag])
        return {'kind': 'wfq', 'virtual_time': self.virtual_time,
                'weights': weights, 'finish': finish}

    def reset(self):
        self.virtual_time = 0
        self.flows = from_sorted([(flow, (weight, 0))
                                  for flow, (weight, _) in items(self.flows)])


def make_policy(spec):
    kind = spec['kind']
    if kind == 'fifo':
        return FifoAlgorithm()
    if kind == 'sp':
        return SpAlgorithm(spec['levels'])
    if kind == 'sff':
        return pFabricAlgorithm()
    return WFQAlgorithm(spec['weights'])
