    cut = a
    end = cut
    while end < hi and ranks[end] == node.key:
        end += 1
    left = _rank_remove_many(node.left, ranks, lo, cut)
    right = _rank_remove_many(node.right, ranks, end, hi)
    return _rank_node(node, node.live - (end - cut), node.served, left, right)


def rank_remove_many(root, ranks):
    """Remove sorted resident ranks (duplicates allowed) in one tree walk."""
    return _rank_remove_many(root, ranks, 0, len(ranks))
